                    e.instituicao && e.instituicao.id === instUsuarioId
                );
                if (eisDaInst.length === 0) return;

                `/registros/filtro/usuarios/${_userId}?instituicaoUsuario=${instUsuarioId}`,
                // OU o valor máximo do campo parcelas (que é o número da parcela atual)
                const totalParcelas = eis.length > 1
                    ? eis.length
                    : Math.max(...eis.map(e => e.parcelas || 1));

                if (totalParcelas > 1) {
                    parcs.push({ registro: r, totalParcelas, ei: eis[0] });
                }
            });

            if (parcs.length === 0) {
            // Filtra apenas eventos com parcelas > 1
                return;
            }

            // Calcula resumo
            const hoje = new Date();
            const ativos = parcs.filter(p => {
                // Encontra o ei desta instituição com parcelas > 1
