    opacity: 0.6;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    margin-bottom: 8px;
}

/* ── Pills (periodicidade, semana, mês, meses) ── */
.ar-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.ar-pill {
    padding: 6px 16px;
    border-radius: 20px;
    border: 2px solid var(--cor-principal);
    background: transparent;
    color: var(--cor-principal);
    font-size: 0.83rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    line-height: 1;
}
.ar-pill:hover { background: var(--cor-tinte-medio); }
.ar-pill.active {
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    box-shadow: 0 2px 8px rgba(0,0,0,0.18);
}
.ar-pill.active::before {
    content: '✓ ';
    font-weight: 700;
    font-size: 0.8em;
}

/* Resumo da recorrência selecionada no toggle */
.ar-recorrente-resumo {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--cor-principal);
    background: var(--cor-tinte-suave);
    border: 1px solid var(--cor-tinte-borda);
    border-radius: 20px;
    padding: 2px 10px;
    margin-left: 6px;
    white-space: nowrap;
    max-width: 260px;
    overflow: hidden;
    text-overflow: ellipsis;
}

.ar-pill-sm { padding: 5px 9px; font-size: 0.78rem; }

.ar-daygrid { gap: 4px; }

.ar-select-small {
    height: 40px;
    border-radius: 8px;
    border: 2px solid var(--cor-principal);
    padding: 0 12px;
    font-size: 0.88rem;
    font-weight: 600;
    color: var(--cor-principal);
    background: transparent;
    cursor: pointer;
    appearance: none;
    margin-top: 4px;
    outline: none;
}
.ar-select-small:focus { border-color: var(--cor-titulo); }

/* ══════════════════════════════════════════════════
   Clear-on-focus state indicator
══════════════════════════════════════════════════ */
.ar-field-submitted {
    background: var(--cor-fundo-campo) !important;
}
.ar-field-submitted + label {
    color: var(--cor-principal) !important;
    opacity: 0.7;
}

/* Empty lote row */
.ar-lote-vazio {
    text-align: center;
    color: var(--cor-texto-secundario);
    font-style: italic;
    padding: 20px;
}

/* Edit/delete action buttons in table */
.ar-lote-actions {
    display: flex;
    gap: 4px;
    align-items: center;
}
.ar-lote-btn {
    width: 30px;
    height: 30px;
    border: none;
    border-radius: 7px;
    background: transparent;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
    transition: background 0.14s, color 0.14s;
}
.ar-lote-btn:hover { background: var(--cor-tinte-medio); }
.ar-lote-btn.delete:hover { background: var(--red-100); color: var(--red-700); }
.ar-lote-btn.edit:hover { background: var(--cor-tinte-medio); color: var(--cor-principal); }
